 * Throws when `memberId` is an owner who is not suspended and no other such
 * owner exists — i.e. when taking them out of that set, whether by demotion,
 * removal or suspension, would leave the workspace unownable. A suspended
 * owner does not count towards keeping it ownable.
 */
async function assertOwnerRetained(
  orgId: OrgId,
  memberId: MemberId,
): Promise<void> {
  const member = await memberRepo.findMemberById(orgId, memberId);
  if (!member || member.role !== "owner" || !isOwnerInGoodStanding(member)) {
    return;
  }

  const page = await memberRepo.listMembers({
    orgId,
    role: "owner",
    limit: OWNER_SCAN_LIMIT,
    cursor: null,
  });

  const remaining = page.items.filter(
    (row) => row.id !== memberId && isOwnerInGoodStanding(row),
  );
  if (remaining.length === 0) {
    throw new Error(
      "An organization must keep at least one owner who is not suspended; transfer ownership first",
    );
  }
}

function isOwnerInGoodStanding(member: Member): boolean {
  return !isArchived(member) && member.status !== "suspended";
}''')
