import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { TenantScopeError } from "@/lib/tenant";
import { activityFilterSchema } from "@/schemas/activity";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import { listActivity, registerActivityListeners } from "@/server/services/activity-service";
import * as commentService from "@/server/services/comment-service";
import { buildDigest, listDigestRecipients } from "@/server/services/digest-service";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import { notify } from "@/server/services/notification-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";
import type { IsoTimestamp } from "@/types/common";

let cleanup: () => void;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = registerActivityListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

async function memberOf(orgId: Parameters<typeof memberRepo.findMember>[0], userId: Parameters<typeof memberRepo.findMember>[1]) {
  const m = await memberRepo.findMember(orgId, userId);
  if (!m) throw new Error("missing");
  return m;
}

describe("suspension", () => {
  it("suspends, is idempotent, reinstates, audits and emits", async () => {
    const t = await createTenant("susp-basic");
    const viewer = await memberOf(t.org.id, t.userIds.viewer);
    const seen: string[] = [];
    const offs = [
      subscribe("member.suspended", (p) => void seen.push(`s:${p.memberId}:${p.userId}:${p.actorId}`)),
      subscribe("member.reinstated", (p) => void seen.push(`r:${p.memberId}`)),
    ];

    const s = await memberService.suspendMember(t.actors.admin, { orgId: t.org.id, memberId: viewer.id });
    expect(s.status).toBe("suspended");
    expect(s.role).toBe("viewer");
    const s2 = await memberService.suspendMember(t.actors.admin, { orgId: t.org.id, memberId: viewer.id });
    expect(s2.status).toBe("suspended");
    expect(seen).toEqual([`s:${viewer.id}:${t.userIds.viewer}:${t.userIds.admin}`]);

    await expect(memberService.resolveActor(t.userIds.viewer, t.org.id)).resolves.toBeNull();
    expect((await orgRepo.listOrgsForUser(t.userIds.viewer)).map((o) => o.id)).not.toContain(t.org.id);
    expect(await memberRepo.countActiveMembers(t.org.id)).toBe(4);
    expect((await usageRepo.recomputeUsage(t.org.id)).seatsUsed).toBe(4);
    expect((await getOrganizationSummary(t.actors.owner, t.org.id)).memberCount).toBe(4);
    const list = await memberService.listMembers(t.actors.owner, { orgId: t.org.id, limit: 10, cursor: null });
    expect(list.items.find((m) => m.id === viewer.id)?.status).toBe("suspended");

    const r = await memberService.reinstateMember(t.actors.admin, { orgId: t.org.id, memberId: viewer.id });
    expect(r.status).toBe("active");
    await memberService.reinstateMember(t.actors.admin, { orgId: t.org.id, memberId: viewer.id });
    expect(seen).toHaveLength(2);
    await expect(memberService.resolveActor(t.userIds.viewer, t.org.id)).resolves.not.toBeNull();
    expect((await orgRepo.listOrgsForUser(t.userIds.viewer)).map((o) => o.id)).toContain(t.org.id);

    const audit = await listActivity(t.actors.owner, { orgId: t.org.id, action: ["member.suspended", "member.reinstated"], limit: 10, cursor: null });
    expect(audit.items).toHaveLength(2);
    expect(audit.items.every((e) => e.subjectKind === "member" && e.subjectId === viewer.id && e.actorId === t.userIds.admin)).toBe(true);
    expect(activityFilterSchema.safeParse({ orgId: t.org.id, action: ["member.suspended", "member.reinstated"], limit: 10, cursor: null }).success).toBe(true);
    offs.forEach((o) => o());
  });

  it("guards", async () => {
    const t = await createTenant("susp-guards");
    const other = await createTenant("susp-guards-other");
    const owner = await memberOf(t.org.id, t.userIds.owner);
    const admin = await memberOf(t.org.id, t.userIds.admin);
    const viewer = await memberOf(t.org.id, t.userIds.viewer);
    await expect(memberService.suspendMember(other.actors.owner, { orgId: t.org.id, memberId: viewer.id })).rejects.toBeInstanceOf(TenantScopeError);
    await expect(memberService.suspendMember(t.actors.owner, { orgId: t.org.id, memberId: "nope" as never })).rejects.toBeInstanceOf(NotFoundError);
    const otherViewer = await memberOf(other.org.id, other.userIds.viewer);
    await expect(memberService.suspendMember(t.actors.owner, { orgId: t.org.id, memberId: otherViewer.id })).rejects.toBeInstanceOf(NotFoundError);
    await expect(memberService.suspendMember(t.actors.member, { orgId: t.org.id, memberId: viewer.id })).rejects.toThrow();
    await expect(memberService.suspendMember(t.actors.admin, { orgId: t.org.id, memberId: admin.id })).rejects.toThrow();
    await expect(memberService.suspendMember(t.actors.admin, { orgId: t.org.id, memberId: owner.id })).rejects.toThrow();
    await expect(memberService.suspendMember(t.actors.owner, { orgId: t.org.id, memberId: owner.id })).rejects.toThrow();
    expect((await memberOf(t.org.id, t.userIds.owner)).status).toBe("active");

    // removed member -> not found
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: viewer.id });
