    await preferenceRepo.upsertPreference({ orgId: t.org.id, userId: t.userIds.member, kind: "comment_created", inApp: true, email: false, digestOnly: true });
    await memberService.suspendMember(t.actors.owner, { orgId: t.org.id, memberId: memberRow.id });

    const events: string[] = [];
    const offs = [subscribe("issue.created", () => void events.push("c")), subscribe("issue.assigned", () => void events.push("a"))];
    await expect(issueService.createIssue(t.actors.owner, issueInput(t.org.id, t.project.id, { assigneeId: t.userIds.member }))).rejects.toBeInstanceOf(memberService.MemberSuspendedError);
    await expect(issueService.assignIssue(t.actors.owner, { orgId: t.org.id, issueId: issue.id, assigneeId: t.userIds.member })).rejects.toMatchObject({ code: "conflict" });
    expect(events).toEqual([]);
    const unassigned = await issueService.assignIssue(t.actors.owner, { orgId: t.org.id, issueId: issue.id, assigneeId: null });
    expect(unassigned.assigneeId).toBeNull();
    await issueService.assignIssue(t.actors.owner, { orgId: t.org.id, issueId: issue.id, assigneeId: t.userIds.admin });
    offs.forEach((o) => o());

    const rows = await notify(t.org.id, "issue_assigned", [t.userIds.member, t.userIds.admin], { title: "x", body: "y", href: "/", actorId: null });
    expect(rows.map((r) => r.recipientId)).toEqual([t.userIds.admin]);

    let payloadIds: readonly string[] = [];
    const off = subscribe("comment.created", (p) => void (payloadIds = p.mentionedUserIds));
    const comment = await commentService.createComment(t.actors.owner, {
      orgId: t.org.id, issueId: issue.id, body: "hi @member and @viewer", parentId: null, mentionedUserIds: [t.userIds.member],
    } as never);
    off();
    expect(comment.mentionedUserIds).toEqual([t.userIds.viewer]);
    expect(payloadIds).toEqual([t.userIds.viewer]);
    void viewer;

    expect(await listDigestRecipients(t.org.id)).not.toContain(t.userIds.member);
    const now = new Date();
    await notificationRepo.insertNotification(t.org.id, { orgId: t.org.id, recipientId: t.userIds.member, kind: "comment_created", title: "old", body: "b", href: "/", actorId: null, channels: ["in_app"] });
    const start = new Date(now.getTime() - 3600_000).toISOString() as IsoTimestamp;
    const end = new Date(now.getTime() + 3600_000).toISOString() as IsoTimestamp;
    expect(await buildDigest(t.org.id, t.userIds.member, start, end)).toBeNull();
    await memberService.reinstateMember(t.actors.owner, { orgId: t.org.id, memberId: memberRow.id });
    expect(await listDigestRecipients(t.org.id)).toContain(t.userIds.member);
    const bundle = await buildDigest(t.org.id, t.userIds.member, start, end);
    expect(bundle?.entries.length).toBeGreaterThanOrEqual(1);
  });
});
